package mx.escuelaministerio.app;

import android.database.sqlite.SQLiteDatabase;
import android.util.Xml;
import org.xmlpull.v1.XmlPullParser;
import java.io.ByteArrayInputStream;
import java.io.ByteArrayOutputStream;
import java.io.InputStream;
import java.time.LocalDate;
import java.util.ArrayList;
import java.util.HashMap;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Locale;
import java.util.Map;
import java.util.zip.ZipEntry;
import java.util.zip.ZipInputStream;

final class HistoricalImportManager {
    private HistoricalImportManager() {}

    static final class Record {String date,room,studentName,helperName;int number;long studentId,helperId;boolean visit;}
    static final class Preview {
        final List<Record> records=new ArrayList<>();final List<String>warnings=new ArrayList<>();int markedCells,unmatchedStudents,invalidGroups;
        String summary(){StringBuilder s=new StringBuilder("Vista previa del histórico\n\nMovimientos listos: ").append(records.size()).append("\nCeldas interpretadas: ").append(markedCells).append("\nAlumnos no identificados: ").append(unmatchedStudents).append("\nAsignaciones inconsistentes: ").append(invalidGroups);if(!warnings.isEmpty()){s.append("\n\nObservaciones:");for(int i=0;i<Math.min(10,warnings.size());i++)s.append("\n• ").append(warnings.get(i));if(warnings.size()>10)s.append("\n• … y ").append(warnings.size()-10).append(" más.");}return s.toString();}
        ImportResult importInto(MinisterioDb db)throws Exception{ImportResult out=new ImportResult();out.backupName=db.backupBeforeHistoricalImport();SQLiteDatabase sql=db.getWritableDatabase();sql.beginTransaction();try{for(Record r:records){int status=db.upsertHistoricalMovement(r.date,r.number,r.room,r.studentId,r.helperId,r.visit);if(status==1)out.added++;else if(status==2)out.duplicates++;else out.conflicts++;}sql.setTransactionSuccessful();}finally{sql.endTransaction();}return out;}
    }
    static final class ImportResult {int added,duplicates,conflicts;String backupName;String summary(){return "Importación histórica terminada.\n\nMovimientos agregados: "+added+"\nDuplicados evitados: "+duplicates+"\nConflictos conservados sin cambios: "+conflicts+"\nRespaldo: "+backupName;}}
    private static final class Cell {String value="";int style;}
    private static final class Row {final Map<Integer,Cell> cells=new HashMap<>();String value(int col){Cell c=cells.get(col);return c==null?"":c.value;}}
    private static final class Participant {String name;boolean helper,visit;}

    static Preview prepare(InputStream source,MinisterioDb db,int year)throws Exception{
        Map<String,byte[]> entries=readEntries(source);List<String> shared=parseShared(entries.get("xl/sharedStrings.xml"));Map<Integer,String> roles=parseStyleRoles(entries.get("xl/styles.xml"));byte[] sheet=null;for(Map.Entry<String,byte[]>e:entries.entrySet())if(e.getKey().startsWith("xl/worksheets/")&&e.getKey().endsWith(".xml")){sheet=e.getValue();break;}if(sheet==null)throw new IllegalArgumentException("El libro no contiene una hoja histórica.");
        Map<Integer,Row> rows=parseSheet(sheet,shared);Row header=rows.get(0),days=rows.get(2);String publisherHeader=header==null?"":header.value(1).toUpperCase(Locale.ROOT).replaceAll("[^A-ZÁÉÍÓÚÑ]","");if(header==null||days==null||!publisherHeader.contains("PUBLICADORES"))throw new IllegalArgumentException("No se reconoció el formato HISTORICO esperado.");
        int firstCol=3,lastCol=days.cells.keySet().stream().mapToInt(x->x).max().orElse(2);int month=monthNumber(header.value(firstCol));if(month==0)throw new IllegalArgumentException("No se pudo reconocer el mes inicial.");int previousDay=0;Map<Integer,String> dates=new HashMap<>();for(int col=firstCol;col<=lastCol;col++){int day=number(days.value(col));if(day<1)continue;if(previousDay>0&&day<previousDay)month++;previousDay=day;dates.put(col,LocalDate.of(year,month,day).toString());}
        Preview out=new Preview();Map<String,List<Participant>> groups=new LinkedHashMap<>();String currentName="";int maxRow=rows.keySet().stream().mapToInt(x->x).max().orElse(3);for(int rowIndex=3;rowIndex<=maxRow;rowIndex++){Row row=rows.get(rowIndex);if(row==null)continue;if(!row.value(1).trim().isEmpty())currentName=row.value(1).trim();String room=normalizeRoom(row.value(2));if(currentName.isEmpty()||room.isEmpty())continue;for(Map.Entry<Integer,String>d:dates.entrySet()){Cell cell=row.cells.get(d.getKey());if(cell==null||cell.value.isEmpty())continue;int assignment=number(cell.value);if(assignment<1)continue;String role=roles.getOrDefault(cell.style,"");if(role.isEmpty()){out.warnings.add(d.getValue()+" "+currentName+": color no reconocido; celda omitida.");continue;}Participant p=new Participant();p.name=currentName;p.helper="HELPER".equals(role);p.visit="VISIT".equals(role);String key=d.getValue()+"|"+room+"|"+assignment;groups.computeIfAbsent(key,k->new ArrayList<>()).add(p);out.markedCells++;}}
        for(Map.Entry<String,List<Participant>>e:groups.entrySet()){String[]k=e.getKey().split("\\|");List<Participant>main=new ArrayList<>(),helpers=new ArrayList<>();boolean visit=false;for(Participant p:e.getValue()){if(p.helper)helpers.add(p);else main.add(p);visit|=p.visit;}if(main.size()!=1||helpers.size()>1){out.invalidGroups++;out.warnings.add(k[0]+" · Sala "+prettyRoom(k[1])+" · asignación "+k[2]+": "+main.size()+" estudiantes y "+helpers.size()+" ayudantes; requiere revisión.");continue;}Record r=new Record();r.date=k[0];r.room=k[1];r.number=Integer.parseInt(k[2]);r.studentName=main.get(0).name;r.helperName=helpers.isEmpty()?"":helpers.get(0).name;r.visit=visit;r.studentId=db.studentIdByImportedName(r.studentName);r.helperId=r.helperName.isEmpty()?0:db.studentIdByImportedName(r.helperName);if(r.studentId<=0||(!r.helperName.isEmpty()&&r.helperId<=0)){out.unmatchedStudents++;String missing=r.studentId<=0?r.studentName:r.helperName;out.warnings.add(r.date+" · «"+missing+"» no coincide de forma única con el catálogo de alumnos.");continue;}out.records.add(r);}
        return out;
    }

    private static Map<String,byte[]>readEntries(InputStream source)throws Exception{Map<String,byte[]>out=new HashMap<>();try(ZipInputStream zip=new ZipInputStream(source)){ZipEntry e;byte[]b=new byte[8192];long total=0;while((e=zip.getNextEntry())!=null){if(e.isDirectory())continue;ByteArrayOutputStream data=new ByteArrayOutputStream();int n;while((n=zip.read(b))!=-1){total+=n;if(total>24L*1024*1024)throw new IllegalArgumentException("El archivo es demasiado grande.");data.write(b,0,n);}out.put(e.getName(),data.toByteArray());}}if(out.isEmpty())throw new IllegalArgumentException("El archivo no es un XLSX válido.");return out;}
    private static List<String>parseShared(byte[]xml)throws Exception{List<String>out=new ArrayList<>();if(xml==null)return out;XmlPullParser p=Xml.newPullParser();p.setInput(new ByteArrayInputStream(xml),"UTF-8");StringBuilder text=null;int event;while((event=p.next())!=XmlPullParser.END_DOCUMENT){if(event==XmlPullParser.START_TAG&&"si".equals(p.getName()))text=new StringBuilder();else if(event==XmlPullParser.START_TAG&&"t".equals(p.getName())&&text!=null)text.append(p.nextText());else if(event==XmlPullParser.END_TAG&&"si".equals(p.getName())&&text!=null){out.add(text.toString());text=null;}}return out;}
    private static Map<Integer,String>parseStyleRoles(byte[]xml)throws Exception{Map<Integer,String>out=new HashMap<>();if(xml==null)return out;XmlPullParser p=Xml.newPullParser();p.setInput(new ByteArrayInputStream(xml),"UTF-8");List<String>fills=new ArrayList<>();boolean inFills=false,inFill=false,inCellXfs=false;String fillRole="";int style=0,event;while((event=p.next())!=XmlPullParser.END_DOCUMENT){String tag=p.getName();if(event==XmlPullParser.START_TAG&&"fills".equals(tag))inFills=true;else if(event==XmlPullParser.END_TAG&&"fills".equals(tag))inFills=false;else if(inFills&&event==XmlPullParser.START_TAG&&"fill".equals(tag)){inFill=true;fillRole="";}else if(inFill&&event==XmlPullParser.START_TAG&&"fgColor".equals(tag)){String rgb=p.getAttributeValue(null,"rgb"),theme=p.getAttributeValue(null,"theme"),tint=p.getAttributeValue(null,"tint");if(rgb!=null&&rgb.endsWith("00B050"))fillRole="MAIN";else if(rgb!=null&&rgb.endsWith("FADF6E"))fillRole="VISIT";else if(("4".equals(theme)||"7".equals(theme))&&tint!=null&&tint.startsWith("0.79"))fillRole="HELPER";}else if(inFill&&event==XmlPullParser.END_TAG&&"fill".equals(tag)){fills.add(fillRole);inFill=false;}else if(event==XmlPullParser.START_TAG&&"cellXfs".equals(tag)){inCellXfs=true;style=0;}else if(event==XmlPullParser.END_TAG&&"cellXfs".equals(tag))inCellXfs=false;else if(inCellXfs&&event==XmlPullParser.START_TAG&&"xf".equals(tag)){int fillId=number(p.getAttributeValue(null,"fillId"));if(fillId>=0&&fillId<fills.size()&&!fills.get(fillId).isEmpty())out.put(style,fills.get(fillId));style++;}}return out;}
    private static Map<Integer,Row>parseSheet(byte[]xml,List<String>shared)throws Exception{Map<Integer,Row>out=new HashMap<>();XmlPullParser p=Xml.newPullParser();p.setInput(new ByteArrayInputStream(xml),"UTF-8");Row row=null;int rowNo=0,col=0,style=0;String type="",raw="";boolean inCell=false;int event;while((event=p.next())!=XmlPullParser.END_DOCUMENT){String tag=p.getName();if(event==XmlPullParser.START_TAG&&"row".equals(tag)){rowNo=Math.max(1,number(p.getAttributeValue(null,"r")))-1;row=new Row();}else if(event==XmlPullParser.START_TAG&&"c".equals(tag)&&row!=null){inCell=true;type=p.getAttributeValue(null,"t");col=columnIndex(p.getAttributeValue(null,"r"));style=number(p.getAttributeValue(null,"s"));raw="";}else if(event==XmlPullParser.START_TAG&&"v".equals(tag)&&inCell)raw=p.nextText();else if(event==XmlPullParser.START_TAG&&"t".equals(tag)&&inCell&&"inlineStr".equals(type))raw+=p.nextText();else if(event==XmlPullParser.END_TAG&&"c".equals(tag)&&row!=null){Cell c=new Cell();c.style=style;c.value=decode(raw,type,shared);row.cells.put(col,c);inCell=false;}else if(event==XmlPullParser.END_TAG&&"row".equals(tag)&&row!=null){out.put(rowNo,row);row=null;}}return out;}
    private static String decode(String raw,String type,List<String>shared){if("s".equals(type)){int i=number(raw);return i>=0&&i<shared.size()?shared.get(i):"";}return raw==null?"":raw.trim();}
    private static int columnIndex(String ref){if(ref==null)return 0;int n=0;for(int i=0;i<ref.length();i++){char c=Character.toUpperCase(ref.charAt(i));if(c<'A'||c>'Z')break;n=n*26+c-'A'+1;}return Math.max(0,n-1);}
    private static int number(String value){try{return(int)Math.round(Double.parseDouble(value));}catch(Exception e){return 0;}}
    private static int monthNumber(String value){String v=value==null?"":value.toUpperCase(Locale.ROOT);String[]m={"ENERO","FEBRERO","MARZO","ABRIL","MAYO","JUNIO","JULIO","AGOSTO","SEPTIEMBRE","OCTUBRE","NOVIEMBRE","DICIEMBRE"};for(int i=0;i<m.length;i++)if(v.contains(m[i]))return i+1;return 0;}
    private static String normalizeRoom(String value){String v=value==null?"":value.toUpperCase(Locale.ROOT);if(v.contains("PRINCIPAL"))return"PRINCIPAL";if(v.contains("AUXILIAR"))return"AUXILIAR";return"";}
    private static String prettyRoom(String room){return"PRINCIPAL".equals(room)?"Principal":"Auxiliar";}
}
